<?php
require_once '../config/database.php';require_once '../includes/auth.php';$id=(int)($_GET['id']??0);$stmt=mysqli_prepare($conn,'SELECT d.*,(SELECT COUNT(*) FROM course c WHERE c.department_id=d.id) course_count,(SELECT COUNT(*) FROM students s WHERE s.department_id=d.id) student_count FROM department d WHERE d.id=?');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$row=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$row){header('Location: index.php');exit;}require_once '../includes/header.php';require_once '../includes/navbar.php';?>
<div class="main-content"><div class="container-fluid"><div class="card shadow-sm"><div class="card-header bg-white d-flex justify-content-between py-3"><h5 class="mb-0">Academic Department Details</h5><a class="btn btn-secondary btn-sm" href="index.php">Back</a></div><div class="card-body p-4"><div class="row g-4"><?php foreach(['Name'=>$row['department_name'],'Code'=>$row['department_code'],'Slug'=>$row['slug'],'Status'=>$row['status']==1?'Active':'Inactive','Courses'=>$row['course_count'],'Students'=>$row['student_count'],'Created'=>$row['created_at'],'Updated'=>$row['updated_at']] as $label=>$value):?><div class="col-md-6"><div class="detail-label"><?=htmlspecialchars($label)?></div><div class="detail-value"><?=htmlspecialchars((string)$value)?></div></div><?php endforeach;?></div></div></div></div></div><?php require_once '../includes/footer.php';?>
